function distinctOrs(nums: number[]): number {
  const seen = new Set<number>();
  for (let i = 0; i < nums.length; i++) {
    let acc = 0;
    for (let j = i; j < nums.length; j++) {
      acc |= nums[j];
      seen.add(acc);
    }
  }
  return seen.size;
}

