function distinctOrs(nums: number[]): number {
  const all = new Set<number>();
  let cur = new Set<number>();
  for (const x of nums) {
    const next = new Set<number>([x]);
    for (const v of cur) next.add(v | x);
    for (const v of next) all.add(v);
    cur = next;
  }
  return all.size;
}

